exports.publicSignature:
/** Rename aliased columns per a { alias: outKey } map (stable, non-mutating). */
export function aliasRow<Row extends Record<string, unknown>>(
  row: Row,
  map: Readonly<Record<string, string>>,
): Record<string, unknown>

export type AllowedTargetStates<Transitions, From extends string> = Transitions extends {
  readonly [k in From]?: readonly (infer To extends string)[];
}
  ? To
  : never;

export function applyOrderBy<B extends OrderTarget>(
  builder: B,
  order: OrderBySpec | undefined,
  pkColumn?: string,
  resolveColumn: (column: string) => string = column => column,
): B

/**
 * Attach a populated relation to a parent row, without mutating it.
 *
 * The type widening is `Populated<T, K>` in `../derive/query.ts`, which reads the declared
 * relation property; this only puts the value there.
 */
export function attachPopulated<P extends Record<string, unknown>, N extends string, V>(
  parent: P,
  name: N,
  value: V,
): P & { [K in N]: V }

/**
 * Assemble a ListResult: limit+1 trim ⇒ hasMore, per-item projection, opt-in total, opaque cursor.
 *
 * Overloaded on `select` so the no-projection call keeps `ListResult<Row>` instead
 * of widening to `ListResult<Row | Partial<Row>>` — the widening is what forced
 * `as ListResult<Entity<T>>` in `@zmdb/repository`'s `list()`.
 */
export function buildListResult<Row extends Record<string, unknown>>(
  rows: readonly Row[],
  opts?: ListOptions,
): ListResult<Row>;

// Optional members admit `undefined` explicitly: under `exactOptionalPropertyTypes` a
// flag map rebuilt by a mapped type over a type *parameter* resolves each member to
// `F[K]` (i.e. `boolean | undefined`), which a bare `?: boolean` rejects. The builder
// chain that first forced this is gone, but `columnMetaFromIR` builds a flag map the same
// way — it sets only the flags the IR asserts — so the looser member type is still what
// makes the result assignable.
//
// `nullable` is required rather than optional, and that asymmetry is deliberate: every
// other flag is a fact a declaration opts into, while nullability is a fact every column
// has one way or the other. A missing `nullable` would read as "not stated", and there is
// nothing for that to mean.
export interface ColumnFlags {
  readonly nullable: boolean;
  readonly primaryKey?: boolean | undefined;
  readonly unique?: boolean | undefined;
  readonly autoIncrement?: boolean | undefined;
  readonly hasDefault?: boolean | undefined;
  readonly length?: number | undefined;
  readonly enum?: readonly string[] | undefined;
  readonly sensitive?: boolean | undefined;
}

export interface ColumnMeta {
  readonly type: SqlType | ExtensionType;
  readonly flags: ColumnFlags;
  readonly default?: unknown;
  readonly references?: { readonly target: string };
  readonly validation?: readonly ValidationRule[];
}

/**
 * Fold a WhereDTO into a query-compiler builder. Bare values become `eq`.
 * Fields/operators are applied in stable object-key order (golden SQL).
 * `and`/`or` groups compose; `or` members are ORed.
 */
export function compileWhere<T extends DeclaredTable, B extends WhereTarget>(
  builder: B,
  where: WhereDTO<T> | undefined,
  resolveColumn: (column: string) => string = column => column,
): B

export function defineEntityStateMachine<
  T extends DeclaredTable,
  StateField extends string,
  const Transitions extends Record<string, readonly string[]>,
  const FieldRestrictions extends { readonly [From in keyof Transitions]?: readonly (keyof UpdateDTO<T>)[] } = {},
>(
  options: EntityStateMachineOptions<T, StateField, Transitions, FieldRestrictions>,
): EntityStateMachine<T, StateField, Transitions, FieldRestrictions>

// ---------------------------------------------------------------------------
// The DTO suite.
// ---------------------------------------------------------------------------

/**
 * The selectable row: every column, required, sensitive columns included, tags
 * preserved. Tags must survive here or the constraints would not survive `Omit`
 * and `Partial` downstream.
 *
 * Relations are not columns and are not here. See `RelationKeys`.
 */
export type Entity<T extends DeclaredTable> = { -readonly [K in ColumnKeys<T>]-?: T[K] };

export interface EntityStateMachine<
  T extends DeclaredTable,
  StateField extends string,
  Transitions extends Record<string, readonly string[]>,
  FieldRestrictions extends { readonly [From in keyof Transitions]?: readonly (keyof UpdateDTO<T>)[] } = {},
> {
  readonly stateField: StateField;
  readonly transitions: Transitions;
  readonly allowedFields?: FieldRestrictions | undefined;
  canTransition<From extends keyof Transitions & string>(from: From, to: string): boolean;
  createUpdatePayload<From extends keyof Transitions & string, To extends Transitions[From][number]>(
    from: From,
    to: To,
    patch?: TransitionPatch<T, StateField, Transitions, FieldRestrictions, From>,
  ): StateUpdateDTO<T, StateField, From, Transitions, PatchableFields<T, Transitions, FieldRestrictions, From>>;
}

export interface EntityStateMachineOptions<
  T extends DeclaredTable,
  StateField extends string,
  Transitions extends Record<string, readonly string[]>,
  FieldRestrictions extends { readonly [From in keyof Transitions]?: readonly (keyof UpdateDTO<T>)[] } = {},
> {
  /**
   * The generated schema value, for inference only — nothing reads it.
   *
   * It is the whole reason this machine knows what a patch may contain: `T` is the
   * declared type, recovered from the value's phantom, and `UpdateDTO<T>` is what the
   * transitions are checked against. Passing a schema for a different table is the one
   * mistake this cannot catch, and it is the same mistake as pointing a repository at
   * the wrong table.
   */
  schema?: TaggedSchema<T>;
  stateField: StateField;
  transitions: Transitions;
  allowedFields?: FieldRestrictions | undefined;
}

// ---------------------------------------------------------------------------
// Type-level assertion utilities
// ---------------------------------------------------------------------------
// Used by the `*.type-test.ts` files next to each module. Those files contain no
// runtime code and are never executed: they are *compiled*, and a broken derived
// type is a typecheck failure like any other.
//
// Why not `expectTypeOf` from vitest? Because vitest only ever *runs* those files
// — `expectTypeOf(...)` is a no-op at runtime and `@ts-expect-error` is inert, so
// every such assertion in a `.spec.ts` was decoration, not a gate — doubly so
// while the package tsconfigs still excluded `**/*.spec.ts`, which also made the
// `@ts-expect-error` directives in them unchecked. Specs are inside the program
// now, and assertions written with `Expect`/`Equal` are enforced by
// `yarn typecheck`, which is what CI runs.

/**
 * Invariant type equality. Stricter than mutual assignability: it distinguishes
 * `any`/`unknown`/`never` and does not collapse optional vs `| undefined`.
 */
export type Equal<A, B> = (<T>() => T extends A ? 1 : 2) extends <T>() => T extends B ? 1 : 2 ? true : false;

// ---------------------------------------------------------------------------
// §4–6 Get/List/Search DTOs (types; result assembly in #166/#169/#172)
// ---------------------------------------------------------------------------
export interface ListDTO<T extends DeclaredTable> {
  where?: WhereDTO<T>;
  orderBy?: OrderByDTO<T>;
  page?: PaginationDTO<T>;
  select?: readonly (keyof Entity<T>)[];
}

export interface ListResult<Row> {
  readonly items: readonly Row[];
  readonly total?: number;
  readonly hasMore: boolean;
  readonly cursor?: string;
}

export type OrderByDTO<T extends DeclaredTable> = ReadonlyArray<{
  column: keyof Entity<T>;
  dir?: OrderDir;
}>;

/** Like {@link WhereTarget}: `this`-returning so folding preserves the builder type. */
export interface OrderTarget {
  orderBy(col: string, dir: OrderDir): this;
  limit(n: number): this;
  offset(n: number): this;
}

export type PaginationDTO<T extends DeclaredTable> =
  | OffsetPage
  | {
      limit: number;
      after?: Partial<Entity<T>> | string | undefined;
      before?: Partial<Entity<T>> | string | undefined;
    };

/**
 * The row plus the relations named by `K`, populated.
 *
 * The key set is `K & keyof T` rather than `K`: `RelationKeys<T>` *is* a subset of `keyof T`
 * by construction, but it is a mapped-type projection and TypeScript will not carry that
 * forward for an unresolved `T`.
 */
export type PopulatedEntity<T extends DeclaredTable, K extends RelationKeys<T> = RelationKeys<T>> = Entity<T> & {
  -readonly [P in K & keyof T]: PopulatedValue<T[P]>;
};

export interface PopulateQuery {
  readonly kind: 'join' | 'batched';
  readonly sql: string;
  readonly parameters: readonly unknown[];
}

/**
 * What a read endpoint may return. `Sensitive` columns are removed from the
 * type, so a leak is a compile error rather than a serializer's responsibility.
 */
export type ReadDTO<T extends DeclaredTable> = Omit<Entity<T>, SensitiveKeys<T>>;

/**
 * One relation, resolved to the pair of columns a join or a batched select matches on.
 *
 * A `RelationIR` says *which* table and *which* column, but not which side holds it — and
 * that is the only thing standing between a declaration and a query. Both readers of a
 * relation resolve it through here, so the join and the batched select cannot disagree about
 * the same declaration (they used to: the repository's join read `fk`/`mappedBy` with one set
 * of fallbacks and its batched select read `childFk`/`parentKey` with another).
 */
export interface ResolvedRelation {
  readonly name: string;
  /** Where the related rows live. */
  readonly targetTable: string;
  /** Ordered columns on the declaring table whose values the join matches. */
  readonly parentKey: readonly string[];
  /** Ordered columns on the target table, positionally paired with `parentKey`. */
  readonly targetKey: readonly string[];
  /** `true` for `oneToMany`: the relation attaches an array, empty where nothing matched. */
  readonly toMany: boolean;
}

// ---------------------------------------------------------------------------
// Entity State Machine & State Transition Helpers
// ---------------------------------------------------------------------------

export type StateTransitions<StateValues extends string | number | symbol = string> = {
  readonly [From in StateValues]?: readonly StateValues[];
};

export type StateUpdateDTO<
  T extends DeclaredTable,
  StateField extends string,
  FromState extends string,
  Transitions,
  AllowedFields extends keyof UpdateDTO<T> = keyof UpdateDTO<T>,
> = Pick<UpdateDTO<T>, Exclude<AllowedFields, StateField>> & {
  [P in StateField]?: AllowedTargetStates<Transitions, FromState>;
};

/** Patch shape: identity and framework-managed columns dropped, everything else optional. */
export type UpdateDTO<T extends DeclaredTable> = Partial<
  Omit<Entity<T>, SerialKeys<T> | PrimaryKeyKeys<T> | SoftDeleteKeys<T>>
>;

export interface ValidationIssue {
  readonly path: string;
  readonly message: string;
  readonly expected?: string;
  readonly value?: unknown;
}

export interface ValidationRule {
  readonly kind: string;
  readonly value?: unknown;
  readonly message?: string;
  /**
   * The argument list, for a rule that came from `@zmdb/aot-validator`'s runtime `tags`.
   *
   * Declared rather than tolerated: `ir/index.ts`'s `ruleArgument` has always read it,
   * and `openapi.spec.ts` has always passed one, so leaving it off the type meant the
   * only two writers of this field disagreed with its declaration.
   */
  readonly args?: readonly unknown[];
}

export type WhereDTO<T extends DeclaredTable> = {
  [K in keyof Entity<T>]?: Entity<T>[K] | FieldOps<Entity<T>[K]>;
} & {
  and?: readonly WhereDTO<T>[];
  or?: readonly WhereDTO<T>[];
  exists?: SubqueryTarget<unknown> | readonly SubqueryTarget<unknown>[];
  notExists?: SubqueryTarget<unknown> | readonly SubqueryTarget<unknown>[];
};

/**
 * A column type supplied by a database extension.
 *
 * The installable extension and the SQL type are separate because PostGIS installs
 * `postgis` and provides `geometry`. Arguments are type parameters rather than a SQL
 * fragment, so reflection can validate and render each one without parsing SQL. This is
 * the one structural marker in the vocabulary: the frozen IR contract names
 * `__zmdbExt` directly, so it needs neither a `declare const` nor a runtime symbol.
 */
export type Ext<E extends string, N extends string, A extends readonly (string | number)[] = []> = {
  readonly __zmdbExt?: [E, N, A];
};

export type ForeignKey<LocalColumns extends string, TargetTable extends string, TargetColumns extends string> = {
  readonly [zmdbForeignKey]?: {
    readonly columns: LocalColumns;
    readonly targetTable: TargetTable;
    readonly targetColumns: TargetColumns;
  };
};

export type ManyToMany<Target extends string, Through extends string> = {
  readonly [zmdbRelation]?: { readonly kind: 'manyToMany'; readonly target: Target; readonly through: Through };
};

export type ManyToOne<Target extends string, Fk extends string> = {
  readonly [zmdbRelation]?: { readonly kind: 'manyToOne'; readonly target: Target; readonly fk: Fk };
};

// ---------------------------------------------------------------------------
// Validation constraints. These are the whole reason the AOT can emit a real
// runtime check from a type: each one puts a literal in a type position.
// ---------------------------------------------------------------------------

export type Min<N extends number> = { readonly [zmdbMin]?: N };

// ---------------------------------------------------------------------------
// Readability aliases. Not tags — these expand to native TypeScript.
// ---------------------------------------------------------------------------

/** `Nullable<string>` is exactly `string | null`. No tag involved. */
export type Nullable<T> = T | null;

export type OneToMany<Target extends string, Fk extends string> = {
  readonly [zmdbRelation]?: { readonly kind: 'oneToMany'; readonly target: Target; readonly fk: Fk };
};

export type OneToOne<Target extends string, Fk extends string> = {
  readonly [zmdbRelation]?: { readonly kind: 'oneToOne'; readonly target: Target; readonly fk: Fk };
};

// ---------------------------------------------------------------------------
// Protobuf tags — facts the wire contract needs that TypeScript cannot state.
// ---------------------------------------------------------------------------

/** Protobuf field number. Required on every property of a protobuf message. */
export type ProtoField<N extends number> = { readonly [zmdbProtoField]?: N };

// ---------------------------------------------------------------------------
// Entity-level tags — applied to the interface itself, via `extends`.
// ---------------------------------------------------------------------------

/** The table an entity maps to. `interface User extends Table<'users'>`. */
export type Table<Name extends string> = { readonly [zmdbTable]?: Name };

export interface ArrayIR {
  readonly kind: 'array';
  readonly element: TypeIR;
  readonly constraints?: Constraints;
}

// ---------------------------------------------------------------------------
// Back-end: the crossing between the two layers (plan D3)
// ---------------------------------------------------------------------------
//
// Having two layers is only useful if something converts between them, once, at the
// boundary. Otherwise every handler decides for itself whether the `at` it was handed is
// a string or a `Date`, which is the state that let the three types disagree.
//
// So: `decodeWire` turns a JSON body into app values, `encodeWire` turns a row back into
// a JSON body, and both read the same `ColumnIR` the validators and the DDL read. They
// convert and nothing else — a value they cannot convert is passed through untouched for
// the validator to reject. That division matters: a decoder that produced `new
// Date('nonsense')` would hand the app layer an `Invalid Date`, which passes `instanceof
// Date` and reaches the database as `NULL` or an error from the driver. Leaving the string
// alone makes the validator say `expected Date`, which is true and actionable.

/** How one named `Codec<'Name'>` column crosses the boundary. */
export interface Codec {
  readonly decode: (wire: unknown) => unknown;
  readonly encode: (app: unknown) => unknown;
}

export interface ColumnIR {
  readonly name: string;
  /** The database column name resolved by the build-time naming strategy. */
  readonly physicalName: string;
  /** Abstract SQL type. The dialect renders the spelling — see plan D3. */
  readonly sql: SqlType | ExtensionType;
  readonly nullable: boolean;
  readonly primaryKey: boolean;
  /** Database-generated. Absent from `CreateDTO`, not merely optional. */
  readonly serial: boolean;
  readonly unique: boolean;
  readonly hasDefault: boolean;
  readonly sensitive: boolean;
  readonly length?: number;
  readonly precision?: readonly [number, number];
  /**
   * The permitted values, **sorted**.
   *
   * Not declaration order, and deliberately so. The producer reads
   * `'free' | 'pro' | 'enterprise'` back out of the checker, which normalises string-literal
   * union members and hands them over in its own order — declaration order is simply not
   * recoverable from a type. A set of permitted values has no order to lose, so sorting is
   * what makes this a function of the declaration rather than of the compiler's internals.
   *
   * Emitters may therefore rely on this being stable across TypeScript versions, which the
   * checker's order is not.
   */
  readonly enum?: readonly string[];
  readonly references?: string;
  readonly onDelete?: ReferentialAction;
  readonly onUpdate?: ReferentialAction;
  readonly codec?: string;
  /**
   * The declared wire type (`WireAs<W>`), for a column whose wire form does not follow
   * from `sql`. A codec's does not: only the declaration knows whether `Money` crosses
   * as a decimal string, a `{ cents }` object or a pair.
   */
  readonly wire?: TypeIR;
  readonly constraints: Constraints;
  /** Named custom rules (`Rule<'name'>`) an emitter must resolve or refuse. */
  readonly rules: readonly string[];
  readonly default?: unknown;
  /**
   * The declared app type: a `json` column's payload shape, or the type behind a codec.
   *
   * There is nowhere in `ColumnMeta` for this to go, which is why `CoreSchema` carries the
   * IR rather than only its projection — a `Settings & Sql<'json'>` read back off the flags
   * alone is just `json`, and the emitted validator would check nothing about the payload.
   */
  readonly payload?: TypeIR;
}

// ---------------------------------------------------------------------------
// Type IR
// ---------------------------------------------------------------------------

/**
 * Numeric and string bounds. Deliberately a flat record rather than the old
 * `ValidationRule[]`: the four walkers disagreed partly because `TypeDescriptor`
 * had `minimum` and `maxLength` but no `maximum` and no `minLength`, so a
 * `Min<18> & Max<120>` column validated differently depending on which one you
 * asked.
 */
export interface Constraints {
  readonly minimum?: number;
  readonly maximum?: number;
  readonly minLength?: number;
  readonly maxLength?: number;
  readonly pattern?: string;
}

export interface Discriminant {
  readonly key: string;
  readonly arms: readonly DiscriminantArm[];
}

export interface DiscriminantArm {
  readonly value: string | number | boolean;
  readonly node: ObjectIR;
}

/** A row as a JSON body: the app→wire encode, for a response. */
export function encodeWire(
  ir: SchemaIR,
  row: Readonly<Record<string, unknown>>,
  codecs: CodecRegistry = {},
): Record<string, unknown>

/** A SQL type installed by a database extension rather than the closed core vocabulary. */
export interface ExtensionType {
  readonly extension: string;
  readonly name: string;
  readonly args?: readonly (string | number)[];
}

export interface ForeignKeyIR {
  readonly columns: readonly string[];
  readonly targetTable: string;
  readonly targetColumns: readonly string[];
}

export interface JsonSchemaObject {
  readonly type: 'object';
  readonly properties: Readonly<Record<string, unknown>>;
  readonly required: readonly string[];
}

// ---------------------------------------------------------------------------
// Back-end: IR → validator type (a `TypeIR` for a whole row or payload)
// ---------------------------------------------------------------------------
//
// The repository used to answer "is this a legal payload for this table" with its own
// walk over `ColumnMeta` — `valueMatchesColumn`, the fourth walker of §1, and the one
// that accepted `Date | string` for a `timestamp` while `toJsonSchema` said ISO string
// and the declared type said `Date`. It does not need a walk. It needs the *type* of a payload,
// which is a `TypeIR`, and then the one runtime walker in `@zmdb/aot-validator` checks
// it — the same walker the emitted code is differentially tested against.
//
// So this is the third back-end onto the same shape, beside the JSON Schema one, and it
// takes the same two decisions from the same place: which columns a variant has
// (`shapeOfVariant`) and what each column's type is at this layer (`appTypeOf` /
// `wireTypeOf`). Nothing here decides anything on its own, which is the point.

/**
 * Which of a column's three types to render (plan D3).
 *
 * `'app'` is what handler code holds: a `timestamp` is a `Date`. `'wire'` is what a JSON
 * body contains: the same column is an ISO-8601 string. A validator has to pick one —
 * accepting both is how the disagreement went unnoticed for so long — so the caller says
 * which side of the boundary it is on.
 */
export type Layer = 'app' | 'wire';

export interface LiteralIR {
  readonly kind: 'literal';
  readonly value: string | number | boolean;
}

export interface NullIR {
  readonly kind: 'null';
}

export interface ObjectIR {
  readonly kind: 'object';
  /** Set when the type had a name, so emitters can hoist a shared helper. */
  readonly name?: string;
  readonly properties: readonly PropertyIR[];
}

export interface PropertyIR {
  readonly name: string;
  readonly type: TypeIR;
  readonly optional: boolean;
  readonly readonly: boolean;
  /** Stable protobuf identity. Required only when this object is emitted as a message. */
  readonly protoField?: number;
}

/** A back-reference to a named `ObjectIR` already on the stack. Cycle guard. */
export interface RefIR {
  readonly kind: 'ref';
  readonly name: string;
}

export interface RelationIR {
  readonly name: string;
  readonly relation: RelationKind;
  readonly target: string;
  /** The foreign-key column, or the join table for `manyToMany`. */
  readonly via: string;
}

export interface ScalarIR {
  readonly kind: 'scalar';
  readonly scalar: ScalarKind;
  /** Protobuf scalar spelling, when the declaration made width/signedness explicit. */
  readonly proto?: ProtoScalar;
  /** JSON Schema `format`, when the scalar has a conventional one. */
  readonly format?: string;
  readonly constraints?: Constraints;
}

/**
 * `integer` is separate from `number` so an emitter can produce
 * `Number.isInteger`, and `date` is separate from `string` so the app type and
 * the wire type can differ without either lying (plan D3).
 */
export type ScalarKind = 'string' | 'number' | 'integer' | 'bigint' | 'boolean' | 'date';

export interface SchemaIR {
  readonly table: string;
  /** The database table name resolved by the build-time naming strategy. */
  readonly physicalTable: string;
  readonly columns: readonly ColumnIR[];
  readonly primaryKey: readonly string[];
  readonly relations: readonly RelationIR[];
  readonly foreignKeys: readonly ForeignKeyIR[];
  readonly ftsTable?: string | boolean;
  /** The nullable timestamp column managed by soft delete. */
  readonly softDelete?: { readonly column: string };
  readonly tableOptions?: TableOptions;
}

/**
 * A column, plus whether the shape it was read from makes it optional.
 *
 * This is what the JSON Schema back-end actually consumes, and it exists because a
 * variant name and a derived type are two spellings of the same information.
 * `toJsonSchema(schema, 'create')` names the variant, and the rule is "a column with a
 * default is optional here". `toJsonSchema<CreateDTO<User>>()` names the type, and the
 * type has already applied that rule — `createdAt?: Date & …` is optional because
 * `CreateDTO` made it so.
 *
 * Collapsing both onto `optional` is what keeps REQ-TF-7 structural rather than tested.
 * A second document generator that reads optionality off a type would be a fifth walker
 * (`PLAN-type-first.md` §1) and would drift the way the other four did.
 */
export interface ShapeColumnIR {
  readonly column: ColumnIR;
  /** The document does not require this property. */
  readonly optional: boolean;
}

// ---------------------------------------------------------------------------
// Schema IR
// ---------------------------------------------------------------------------

export interface TableOptions {
  readonly shardKey?: readonly string[];
  readonly sortKey?: readonly string[];
  readonly rowstore?: true;
}

export interface TupleIR {
  readonly kind: 'tuple';
  readonly elements: readonly TypeIR[];
}

export interface UndefinedIR {
  readonly kind: 'undefined';
}

export interface UnionIR {
  readonly kind: 'union';
  readonly members: readonly TypeIR[];
}

export interface UnknownIR {
  readonly kind: 'unknown';
}

/**
 * A first-class node, not an absence. A gap has to be visible: the transformer
 * bug fixed in `f70186c6` happened because an unrecognised type produced a
 * *partial* answer that looked like a real one. An `unsupported` node makes the
 * emitter refuse and the build fail with the reason (plan D4).
 */
export interface UnsupportedIR {
  readonly kind: 'unsupported';
  readonly reason: string;
  /** The type as written, when the producer can recover it. */
  readonly source?: string;
}

/**
 * Everything that is a column: a data key that is not a relation.
 *
 * Spelled as its own projection rather than as a subtraction. `Exclude<AllKeys<T>,
 * RelationKeys<T>>` does not compile: for an unresolved `T` both operands normalise to
 * the same deferred expression, so the subtraction yields `never`, and then
 * `Pick<Entity<T>, DefaultKeys<T>>` is an error because nothing is a key of an entity
 * with no keys.
 */
export type ColumnKeys<T> = {
  [K in keyof T]-?: NonNullable<T[K]> extends AnyRelation ? never : K extends string ? K : never;
}[keyof T];

// ---------------------------------------------------------------------------
// The DTO suite.
// ---------------------------------------------------------------------------

/**
 * The selectable row: every column, required, sensitive columns included, tags
 * preserved. Tags must survive here or the constraints would not survive `Omit`
 * and `Partial` downstream.
 *
 * Relations are not columns and are not here. See `RelationKeys`.
 */
export type Entity<T extends DeclaredTable> = { -readonly [K in ColumnKeys<T>]-?: T[K] };

// ---------------------------------------------------------------------------
// §4 GetDTO
// ---------------------------------------------------------------------------
export interface GetOptions<T extends DeclaredTable> {
  select?: readonly (keyof Entity<T>)[];
  /**
   * The relations to fetch alongside the row.
   *
   * `RelationKeys<T>` rather than `readonly string[]`: a declared type names its relations,
   * so a misspelled one is a compile error rather than a relation that silently does not
   * arrive. It was a bare `string[]` while this family was keyed by the schema value, which
   * carries no relations to check a name against.
   */
  populate?: readonly RelationKeys<T>[];
}

// ---------------------------------------------------------------------------
// Key filters.
// ---------------------------------------------------------------------------
//
// `NonNullable<T[K]>` rather than a bare `T[K]` is load-bearing. A nullable
// column with a default is declared `(string & HasDefault) | null`, and `null` is
// not assignable to a weak object type, so the union as a whole does not match
// `HasDefault`. Testing the non-nullable arm is what makes a nullable defaulted
// column optional on insert instead of required. `tagged-dto.type-test.ts` pins
// this down: it is exactly the sort of thing that silently returns `never`.
//
// `-?` strips optionality from the probe so an already-optional property is still
// examined under `exactOptionalPropertyTypes`.
//
// Symbol keys are filtered out everywhere below: entity-level tags (`Table`,
// `Fts`, `SoftDelete`, `ForeignKey`) arrive through `extends` and would
// otherwise show up in `keyof`.

export type KeysCarrying<T, Tag> = {
  [K in keyof T]-?: NonNullable<T[K]> extends Tag ? (K extends string ? K : never) : never;
}[keyof T];

// ---------------------------------------------------------------------------
// §4–6 Get/List/Search DTOs (types; result assembly in #166/#169/#172)
// ---------------------------------------------------------------------------
export interface ListDTO<T extends DeclaredTable> {
  where?: WhereDTO<T>;
  orderBy?: OrderByDTO<T>;
  page?: PaginationDTO<T>;
  select?: readonly (keyof Entity<T>)[];
}

export interface ListResult<Row> {
  readonly items: readonly Row[];
  readonly total?: number;
  readonly hasMore: boolean;
  readonly cursor?: string;
}

export type OrderByDTO<T extends DeclaredTable> = ReadonlyArray<{
  column: keyof Entity<T>;
  dir?: OrderDir;
}>;

export type PaginationDTO<T extends DeclaredTable> =
  | OffsetPage
  | {
      limit: number;
      after?: Partial<Entity<T>> | string | undefined;
      before?: Partial<Entity<T>> | string | undefined;
    };

/**
 * The row plus the relations named by `K`, populated.
 *
 * The key set is `K & keyof T` rather than `K`: `RelationKeys<T>` *is* a subset of `keyof T`
 * by construction, but it is a mapped-type projection and TypeScript will not carry that
 * forward for an unresolved `T`.
 */
export type PopulatedEntity<T extends DeclaredTable, K extends RelationKeys<T> = RelationKeys<T>> = Entity<T> & {
  -readonly [P in K & keyof T]: PopulatedValue<T[P]>;
};

/**
 * What a read endpoint may return. `Sensitive` columns are removed from the
 * type, so a leak is a compile error rather than a serializer's responsibility.
 */
export type ReadDTO<T extends DeclaredTable> = Omit<Entity<T>, SensitiveKeys<T>>;

/** Patch shape: identity and framework-managed columns dropped, everything else optional. */
export type UpdateDTO<T extends DeclaredTable> = Partial<
  Omit<Entity<T>, SerialKeys<T> | PrimaryKeyKeys<T> | SoftDeleteKeys<T>>
>;

export type WhereDTO<T extends DeclaredTable> = {
  [K in keyof Entity<T>]?: Entity<T>[K] | FieldOps<Entity<T>[K]>;
} & {
  and?: readonly WhereDTO<T>[];
  or?: readonly WhereDTO<T>[];
  exists?: SubqueryTarget<unknown> | readonly SubqueryTarget<unknown>[];
  notExists?: SubqueryTarget<unknown> | readonly SubqueryTarget<unknown>[];
};

export type AggregateResult<T extends DeclaredTable, Spec extends AggregateSpec<T>> = {
  [K in Spec['groupBy'] extends readonly (infer G extends keyof Entity<T>)[] ? G : never]: Entity<T>[K];
} & {
  [K in keyof Spec['computed']]: AggComputedType<T, Spec['computed'][K]>;
};

export interface AggregateSpec<T extends DeclaredTable> {
  joins?:
    | readonly (RelationKeys<T> & string)[]
    | readonly { relation: RelationKeys<T> & string; kind?: 'inner' | 'left' | 'right' }[];
  where?: WhereDTO<T> | Record<string, unknown>;
  groupBy?: readonly AggregateColumn<T>[];
  computed: Record<string, ComputedSpec<T>>;
  having?: Readonly<{ column: AggregateColumn<T>; op: string; value: unknown }>;
  orderBy?: ReadonlyArray<{ column: AggregateColumn<T>; dir?: OrderDir }>;
  limit?: number;
  offset?: number;
}

export function applyOrderBy<B extends OrderTarget>(
  builder: B,
  order: OrderBySpec | undefined,
  pkColumn?: string,
  resolveColumn: (column: string) => string = column => column,
): B

/**
 * Assemble a ListResult: limit+1 trim ⇒ hasMore, per-item projection, opt-in total, opaque cursor.
 *
 * Overloaded on `select` so the no-projection call keeps `ListResult<Row>` instead
 * of widening to `ListResult<Row | Partial<Row>>` — the widening is what forced
 * `as ListResult<Entity<T>>` in `@zmdb/repository`'s `list()`.
 */
export function buildListResult<Row extends Record<string, unknown>>(
  rows: readonly Row[],
  opts?: ListOptions,
): ListResult<Row>;

/** Assemble a SearchResult (reuses buildListResult; preserves _score on hits). */
export function buildSearchResult<Row extends Record<string, unknown>>(
  rows: readonly SearchHit<Row>[],
  opts?: { limit?: number; select?: readonly (keyof Row)[]; total?: number },
): SearchResult<Row | Partial<Row>>

/**
 * Fold a WhereDTO into a query-compiler builder. Bare values become `eq`.
 * Fields/operators are applied in stable object-key order (golden SQL).
 * `and`/`or` groups compose; `or` members are ORed.
 */
export function compileWhere<T extends DeclaredTable, B extends WhereTarget>(
  builder: B,
  where: WhereDTO<T> | undefined,
  resolveColumn: (column: string) => string = column => column,
): B

export interface ComputedSpec<T extends DeclaredTable = DeclaredTable> {
  fn: AggFn;
  column?: AggregateColumn<T>;
  raw?: string;
}

export interface FieldOps<V> {
  eq?: V | SubqueryTarget<V>;
  ne?: V | SubqueryTarget<V>;
  lt?: V | SubqueryTarget<V>;
  lte?: V | SubqueryTarget<V>;
  gt?: V | SubqueryTarget<V>;
  gte?: V | SubqueryTarget<V>;
  in?: readonly V[] | SubqueryTarget<V>;
  nin?: readonly V[] | SubqueryTarget<V>;
  like?: V extends string ? string | SubqueryTarget<string> : never;
  ilike?: V extends string ? string | SubqueryTarget<string> : never;
  l2?: VectorOperand<V>;
  cosine?: VectorOperand<V>;
  ip?: VectorOperand<V>;
  isNull?: boolean;
  notNull?: boolean;
}

// ---------------------------------------------------------------------------
// §4 GetDTO
// ---------------------------------------------------------------------------
export interface GetOptions<T extends DeclaredTable> {
  select?: readonly (keyof Entity<T>)[];
  /**
   * The relations to fetch alongside the row.
   *
   * `RelationKeys<T>` rather than `readonly string[]`: a declared type names its relations,
   * so a misspelled one is a compile error rather than a relation that silently does not
   * arrive. It was a bare `string[]` while this family was keyed by the schema value, which
   * carries no relations to check a name against.
   */
  populate?: readonly RelationKeys<T>[];
}

/** Apply a Get's select projection to a fetched row. */
export function getResult<Row extends Record<string, unknown>>(
  row: Row,
  opts?: { select?: readonly (keyof Row)[] },
): Row | Partial<Row>

// ---------------------------------------------------------------------------
// §4–6 Get/List/Search DTOs (types; result assembly in #166/#169/#172)
// ---------------------------------------------------------------------------
export interface ListDTO<T extends DeclaredTable> {
  where?: WhereDTO<T>;
  orderBy?: OrderByDTO<T>;
  page?: PaginationDTO<T>;
  select?: readonly (keyof Entity<T>)[];
}

export interface ListResult<Row> {
  readonly items: readonly Row[];
  readonly total?: number;
  readonly hasMore: boolean;
  readonly cursor?: string;
}

export type OrderByDTO<T extends DeclaredTable> = ReadonlyArray<{
  column: keyof Entity<T>;
  dir?: OrderDir;
}>;

/**
 * Schema-agnostic views of the order/page DTOs — exactly the fields the folders
 * read. `OrderByDTO<T>`/`PaginationDTO<T>` are structurally assignable to these
 * for *any* `T`, so callers pass their own typed DTO with no
 * `as OrderByDTO<CoreSchema<string>>` widening cast (which is what leaked into
 * consumer code, cf. COOKBOOK "sorting" example).
 */
export type OrderBySpec = ReadonlyArray<{
  column: PropertyKey;
  dir?: OrderDir;
}>;

/** Like {@link WhereTarget}: `this`-returning so folding preserves the builder type. */
export interface OrderTarget {
  orderBy(col: string, dir: OrderDir): this;
  limit(n: number): this;
  offset(n: number): this;
}

export type PaginationDTO<T extends DeclaredTable> =
  | OffsetPage
  | {
      limit: number;
      after?: Partial<Entity<T>> | string | undefined;
      before?: Partial<Entity<T>> | string | undefined;
    };

// `offset?: number | undefined` (not `offset?: number`) so callers under
// `exactOptionalPropertyTypes` can forward a possibly-absent offset positionally.
export type PaginationSpec = {
  limit: number;
  offset?: number | undefined;
  after?: Record<string, unknown> | string | undefined;
  before?: Record<string, unknown> | string | undefined;
};

export interface SearchDTO<T extends DeclaredTable> {
  query: string;
  columns: readonly (keyof Entity<T>)[];
  where?: WhereDTO<T>;
  page?: PaginationDTO<T>;
  rank?: boolean;
}

export type SubqueryTarget<V = unknown> =
  | SelectBuilder<V>
  | { compile(): CompiledQuery; readonly _type?: V }
  | {
      table: string;
      select?: readonly string[];
      where?: WhereDTO<UnknownRow>;
      readonly _type?: V;
    };

// ---------------------------------------------------------------------------
// WhereDTO + operator set
// ---------------------------------------------------------------------------
/**
 * A row of a table the caller named with a string.
 *
 * A subquery target is `{ table: 'orders' }` — a table *name*, not a declared type — so there
 * is nothing for its filter to be keyed by. This says exactly that much and no more: every
 * property is a column of some SQL type, and none of them is a relation, which is what keeps
 * `WhereDTO` willing to derive from it. It is a named type rather than an inline
 * `Record<string, unknown>` so that it stays the one corner of the query surface that is
 * keyed by string; everything else is keyed by the interface the table was declared as.
 */
export interface UnknownRow {
  readonly [column: string]: string | number | boolean | bigint | Date | null;
}

export type WhereDTO<T extends DeclaredTable> = {
  [K in keyof Entity<T>]?: Entity<T>[K] | FieldOps<Entity<T>[K]>;
} & {
  and?: readonly WhereDTO<T>[];
  or?: readonly WhereDTO<T>[];
  exists?: SubqueryTarget<unknown> | readonly SubqueryTarget<unknown>[];
  notExists?: SubqueryTarget<unknown> | readonly SubqueryTarget<unknown>[];
};

/**
 * Minimal structural view of the query-compiler SelectBuilder we drive.
 *
 * The methods return `this` (not `WhereTarget`), so folding a DTO into a builder
 * preserves the caller's concrete builder type. That is what lets `compileWhere`
 * return `B` without asserting: previously the chain widened to `WhereTarget` and
 * every helper ended in `return b as B`.
 */
export interface WhereTarget {
  where(col: string, op: string, value: unknown): this;
  orWhere(col: string, op: string, value: unknown): this;
  whereGroup?(predicates: readonly ComparisonPredicate[]): this;
  orWhereGroup?(predicates: readonly ComparisonPredicate[]): this;
  whereExists?(subquery: unknown): this;
  orWhereExists?(subquery: unknown): this;
  whereNotExists?(subquery: unknown): this;
  orWhereNotExists?(subquery: unknown): this;
  whereIn?(col: string, values: readonly unknown[]): this;
  orWhereIn?(col: string, values: readonly unknown[]): this;
  whereNotIn?(col: string, values: readonly unknown[]): this;
  orWhereNotIn?(col: string, values: readonly unknown[]): this;
}

/**
 * A build-time mapping from declared TypeScript names to physical SQL names.
 *
 * The reflector calls these functions once and stores their answers in `SchemaIR`.
 * Query compilation and row handling never receive a strategy.
 */
export interface NamingStrategy {
  readonly column?: (property: string, context: { readonly table: string }) => string;
  readonly table?: (declared: string) => string;
  readonly index?: (table: string, columns: readonly string[], unique: boolean) => string;
}

/** Rename aliased columns per a { alias: outKey } map (stable, non-mutating). */
export function aliasRow<Row extends Record<string, unknown>>(
  row: Row,
  map: Readonly<Record<string, string>>,
): Record<string, unknown>

/**
 * Attach a populated relation to a parent row, without mutating it.
 *
 * The type widening is `Populated<T, K>` in `../derive/query.ts`, which reads the declared
 * relation property; this only puts the value there.
 */
export function attachPopulated<P extends Record<string, unknown>, N extends string, V>(
  parent: P,
  name: N,
  value: V,
): P & { [K in N]: V }

export interface PopulateQuery {
  readonly kind: 'join' | 'batched';
  readonly sql: string;
  readonly parameters: readonly unknown[];
}

/**
 * One relation, resolved to the pair of columns a join or a batched select matches on.
 *
 * A `RelationIR` says *which* table and *which* column, but not which side holds it — and
 * that is the only thing standing between a declaration and a query. Both readers of a
 * relation resolve it through here, so the join and the batched select cannot disagree about
 * the same declaration (they used to: the repository's join read `fk`/`mappedBy` with one set
 * of fallbacks and its batched select read `childFk`/`parentKey` with another).
 */
export interface ResolvedRelation {
  readonly name: string;
  /** Where the related rows live. */
  readonly targetTable: string;
  /** Ordered columns on the declaring table whose values the join matches. */
  readonly parentKey: readonly string[];
  /** Ordered columns on the target table, positionally paired with `parentKey`. */
  readonly targetKey: readonly string[];
  /** `true` for `oneToMany`: the relation attaches an array, empty where nothing matched. */
  readonly toMany: boolean;
}

// #175 — read-variant envelopes. list wraps the entity in a paged envelope;
// search adds an optional _score to each item. Build-time, deterministic.
export interface EnvelopeSchema {
  readonly type: 'object';
  readonly properties: Readonly<Record<string, unknown>>;
  readonly required: readonly string[];
}

export interface JsonSchemaObject {
  readonly type: 'object';
  readonly properties: Readonly<Record<string, unknown>>;
  readonly required: readonly string[];
}

export function toOpenApiComponents(schemas: readonly CoreSchema<string>[]): {
  schemas: Record<string, JsonSchemaObject>;
}

/**
 * A column type the library does not know, described by its owner.
 *
 * Three types, because a column has three (plan D3): `Wire` is what JSON carries,
 * `TS` is what handler code holds, and `DB` is what the driver binds. A codec that
 * named only two of them left the third to be guessed, and the guess was "the same
 * as the app type" — which is how a `Money` instance ended up being handed to
 * `JSON.stringify` and to a query parameter unchanged.
 *
 * All four functions are required. A codec whose `toWire` was optional would be a
 * codec that sometimes converts, and the caller cannot tell which kind it has.
 */
export interface CustomType<Wire, TS, DB = unknown> {
  /** DDL type, e.g. `'jsonb'`. Dialect spelling is the emitter's business. */
  readonly sqlType: string;
  /** Serialise for the driver. */
  readonly toDb: (value: TS) => DB;
  /** Parse a driver row value. */
  readonly fromDb: (raw: DB) => TS;
  /** Serialise for a JSON response. */
  readonly toWire: (value: TS) => Wire;
  /** Parse a JSON request body value. */
  readonly fromWire: (raw: Wire) => TS;
}

/** A database column projected under an application-facing result key. */
export interface AliasedColumn {
  readonly column: string;
  readonly alias: string;
}

export interface AliasedDistanceExpression<C extends string = string> {
  readonly [EXTENSION_EXPRESSION]: 'aliased-distance';
  readonly kind: 'aliased';
  readonly expression: DistanceExpression<C>;
  readonly alias: string;
}

export interface AppliedMigration {
  readonly version: number;
  readonly name: string;
  /** `null` identifies a ledger row written before checksums were introduced. */
  readonly checksum: string | null;
}

export interface CatalogColumnSnapshot extends ColumnSnapshot {
  readonly catalogType: string;
  readonly default?: string;
  /** Dialect catalog evidence for a generated column. Drift comparison may ignore it. */
  readonly generated?: {
    readonly expression: string;
    readonly stored: boolean;
  };
}

export interface CatalogForeignKeySnapshot {
  readonly name: string;
  readonly columns: readonly string[];
  readonly targetTable: string;
  readonly targetColumns: readonly string[];
  readonly onDelete: ReferentialAction;
  readonly onUpdate: ReferentialAction;
}

export type CatalogIndexColumn =
  | string
  | { readonly column: string; readonly opclass?: string }
  | { readonly expr: string; readonly opclass?: string };

export interface CatalogIndexSnapshot {
  readonly name: string;
  readonly columns: readonly CatalogIndexColumn[];
  readonly unique: boolean;
  readonly method?: string;
  readonly where?: string;
}

export interface CatalogSchemaSnapshot extends Omit<SchemaSnapshot, 'tables'> {
  readonly tables: readonly CatalogTableSnapshot[];
  readonly extensions: readonly { readonly name: string; readonly schema?: string }[];
  readonly warnings: readonly CatalogWarning[];
}

export interface CatalogSelection {
  readonly schemas?: readonly string[];
  readonly include?: readonly string[];
  readonly exclude?: readonly string[];
}

export interface CatalogTableSnapshot extends Omit<TableSnapshot, 'columns'> {
  readonly columns: readonly CatalogColumnSnapshot[];
  readonly primaryKey: readonly string[];
  readonly foreignKeys: readonly CatalogForeignKeySnapshot[];
  readonly indexes: readonly CatalogIndexSnapshot[];
}

export interface CatalogWarning {
  readonly table: string;
  readonly column?: string;
  readonly reason: string;
}

export type ChangeOp =
  | { readonly kind: 'create_extension'; readonly name: string; readonly schema?: string }
  | {
      readonly kind: 'create_table';
      readonly table: string;
      readonly columns: readonly ColumnSnapshot[];
      readonly primaryKey: readonly string[];
      readonly foreignKeys: readonly ForeignKeySnapshot[];
      readonly tableOptions?: TableOptions;
    }
  | { readonly kind: 'drop_table'; readonly table: string }
  | { readonly kind: 'add_column'; readonly table: string; readonly column: ColumnSnapshot }
  | { readonly kind: 'drop_column'; readonly table: string; readonly column: string }
  | {
      readonly kind: 'alter_column_type';
      readonly table: string;
      readonly column: string;
      readonly from: string | ExtensionType;
      readonly to: string | ExtensionType;
      /** Required by dialects whose ALTER COLUMN restates nullability. */
      readonly fromNullable?: boolean;
      /** Required by dialects whose ALTER COLUMN restates nullability. */
      readonly toNullable?: boolean;
    }
  | {
      readonly kind: 'alter_primary_key';
      readonly table: string;
      readonly from: readonly string[];
      readonly to: readonly string[];
    }
  | { readonly kind: 'add_foreign_key'; readonly table: string; readonly fk: ForeignKeySnapshot }
  | { readonly kind: 'drop_foreign_key'; readonly table: string; readonly name: string };

/** A deliberately closed expression over the column named by its SET key. */
export type ColumnExpr<T> = ExpressionBrand<T> &
  (
    | { readonly op: 'add' | 'sub' | 'mul'; readonly by: T }
    | { readonly op: 'not' }
    | { readonly op: 'concat'; readonly with: string }
    | { readonly op: 'coalesce'; readonly fallback: T }
    | { readonly op: 'proposed' }
  );

export interface ColumnSnapshot {
  readonly name: string;
  /**
   * The **abstract** column type — `'timestamp'`, not `'TIMESTAMPTZ'`.
   *
   * A snapshot is a record of what the schema says, so it must not name a dialect: the
   * same snapshot is diffed and then emitted for Postgres, MySQL and SQLite. `ddlType`
   * is where it becomes a real one.
   */
  readonly type: string | ExtensionType;
  readonly nullable: boolean;
  readonly primaryKey: boolean;
  /** `varchar(255)` → `255`. MySQL rejects a `VARCHAR` with no length. */
  readonly length?: number | undefined;
  /** Carried so dialect-specific DDL can validate or emit the declaration. */
  readonly unique?: boolean;
}

/**
 * One comparison in a WHERE or HAVING list. `connector` says how it attaches to
 * the predicate before it and is ignored on the first one; builders that only
 * ever conjoin can leave it out.
 */
export interface ComparisonPredicate {
  readonly kind?: 'comparison';
  readonly col: string;
  readonly op: string;
  readonly value: unknown;
  readonly connector?: 'AND' | 'OR' | undefined;
}

export interface CompiledQuery {
  readonly text: string;
  readonly parameters: readonly unknown[];
  readonly telemetry?: QueryTelemetry;
}

export function createQueryCompiler<Name extends string>(
  dialect: SqlDialect<Name>,
  options?: QueryCompilerOptions,
): QueryCompiler;

export interface DatabaseCapabilities {
  readonly returning: Readonly<Record<ReturningStatement, boolean>>;
  readonly transactionalDdl: boolean;
  readonly schemas: boolean;
  readonly sequences: boolean;
  readonly generatedColumns: boolean;
  readonly partialIndexes: boolean;
  readonly foreignKeys: boolean;
  readonly rowLevelSecurity: boolean;
  readonly streaming: boolean;
  readonly cancellation: boolean;
}

export interface DeleteBuilder {
  where(col: string, op: Operator, value: unknown): DeleteBuilder;
  orWhere(col: string, op: Operator, value: unknown): DeleteBuilder;
  whereGroup(predicates: readonly ComparisonPredicate[]): DeleteBuilder;
  whereIn(col: string, values: readonly unknown[]): DeleteBuilder;
  whereNotIn(col: string, values: readonly unknown[]): DeleteBuilder;
  returning(cols?: readonly ReturningColumn[]): DeleteBuilder;
  compile(): CompiledQuery;
}

export interface DialectCompiler {
  returning(context: DialectReturningContext): DialectReturningSql;
  upsert(context: DialectUpsertContext): string;
}

export interface DialectOutbox {
  readonly createTable: string;
  readonly pendingIndex: 'filtered' | 'full';
  readonly epochLiteral: string;
  readonly createdAtDefault: string;
  boundedTextType(length: number): string;
}

export type DialectReturningColumn =
  | string
  | {
      readonly column: string;
      readonly alias: string;
    };

export interface DialectReturningContext {
  readonly dialect: SqlDialect;
  readonly statement: ReturningStatement;
  readonly row: 'new' | 'old';
